(() => {
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, null);
  let node;
  while ((node = walker.nextNode())) {
    if (node.nodeValue && node.nodeValue.trim() === 'cedar-flash-8252') {
      const el = node.parentElement;
      const rect = el.getBoundingClientRect();
      // Try to give a unique selector
      let path = '';
      let cur = el;
      while (cur && cur !== document.body) {
        let part = cur.tagName.toLowerCase();
        if (cur.id) { part = '#' + cur.id; path = part + (path ? '>' + path : ''); break; }
        if (cur.className && typeof cur.className === 'string') {
          part += '.' + cur.className.trim().split(/\s+/).join('.');
        }
        const sib = cur.parentElement ? Array.from(cur.parentElement.children).filter(c => c.tagName === cur.tagName) : [];
        if (sib.length > 1) {
          part += ':nth-of-type(' + (sib.indexOf(cur) + 1) + ')';
        }
        path = part + (path ? '>' + path : '');
        cur = cur.parentElement;
      }
      return { tag: el.tagName, text: el.textContent, selector: path, rect: { x: rect.x, y: rect.y, w: rect.width, h: rect.height } };
    }
  }
  return null;
})()
